<?php defined('BASEPATH') or exit('No direct script access allowed'); ?><div id="widget-sc-calculator" class="widget relative"><div class="panel_s"><div class="panel-body"><div class="widget-dragger"></div><h4 class="tw-font-semibold tw-mt-0"><i class="fa-solid fa-calculator text-info"></i> Calculator</h4><input id="sc-widget-calc" class="form-control" placeholder="1250 * 0.50"><button type="button" class="btn btn-info btn-sm mtop10" onclick="var e=document.getElementById('sc-widget-calc'),r=document.getElementById('sc-widget-result');try{if(!/^[0-9+\-*/().% ]+$/.test(e.value))throw 0;r.textContent=Function('return ('+e.value.replace(/%/g,'/100')+')')()}catch(x){r.textContent='Invalid calculation'}">Calculate</button><strong id="sc-widget-result" class="tw-block tw-mt-2"></strong></div></div></div>